# -*- coding: utf-8 -*-
def story(i, pp, hdr, scene, story_t, remark, note="Urdu text; transcribed best-effort from scan."):
    blocks = []
    if hdr:
        blocks.append({"type": "header", "text": hdr})
    blocks.append({"type": "image", "text": "Picture for the story (photo/illustration)"})
    blocks.append({"type": "subheading", "text": "منظر:"})
    blocks.append({"type": "paragraph", "text": scene})
    blocks.append({"type": "subheading", "text": "کہانی:"})
    blocks.append({"type": "paragraph", "text": story_t})
    blocks.append({"type": "subheading", "text": "تبصرہ:"})
    blocks.append({"type": "paragraph", "text": remark})
    blocks.append({"type": "paragraph", "text": "[note] " + note})
    return {"index": i, "printed_page": pp, "blocks": blocks}

